on note
  ignore_event($EVENT_ID)
  inc($keys_down)
  %src_held[$EVENT_NOTE] := 1
  $p_vel := $EVENT_VELOCITY
  if ($hum_vel > 0)
    $p_vel := $p_vel + random(0 - $hum_vel, $hum_vel)
    if ($p_vel < 1)
      $p_vel := 1
    end if
    if ($p_vel > 127)
      $p_vel := 127
    end if
  end if
  $sc_note := $EVENT_NOTE
  call scale_snap
  $bc_root := $sc_note
  $bc_src := $EVENT_NOTE
  call build_chord
  if ($arp_mode > 0)
    $arp_lastvel := $p_vel
    $aa_src := $EVENT_NOTE
    call arp_add
    exit
  end if
  if (%src_n[$EVENT_NOTE] > 0)
    $rs_src := $EVENT_NOTE
    $rs_time := $retrig_us
    call release_src
  end if
  if ($hum_time > 0)
    wait(random(0, $hum_time * 1000) + 1)
  end if
  $p_i := 0
  $p_cnt := %ch_n[$EVENT_NOTE]
  while ($p_i < $p_cnt)
    if ($p_i > 0 and $strum > 0)
      wait($strum * 1000)
    end if
    if (%src_held[$EVENT_NOTE] = 1 or $pedal = 1)
      $sn_note := %ch_note[$EVENT_NOTE * 8 + $p_i]
      $sn_vel := $p_vel
      $sn_off := 0
      $sn_fade := -1
      call start_note
      $rs_src := $EVENT_NOTE
      call reg_new
    else
      $p_i := $p_cnt
    end if
    inc($p_i)
  end while
end on

on release
  dec($keys_down)
  if ($keys_down < 0)
    $keys_down := 0
  end if
  %src_held[$EVENT_NOTE] := 0
  if ($arp_mode > 0)
    if ($arp_latch = 0)
      $ar_src := $EVENT_NOTE
      call arp_remove
    end if
    exit
  end if
  if ($pedal = 1)
    %src_sus[$EVENT_NOTE] := 1
  else
    $rs_src := $EVENT_NOTE
    $rs_time := $rel_us
    call release_src
  end if
end on

on controller
  if ($CC_NUM = 64 and $use_pedal = 1)
    if (%CC[64] >= 64)
      $pedal := 1
    else
      if ($pedal = 1)
        $pedal := 0
        call pedal_up
      end if
    end if
  end if
  if ($CC_NUM = 120 or $CC_NUM = 123)
    $rs_time := 20000
    call release_all
  end if
  if ($CC_NUM = $VCC_PITCH_BEND)
    $cb_v := (%CC[$VCC_PITCH_BEND] * $pb_range * 100) / 8191 * 1000
    change_tune($ALL_EVENTS, $cb_v - $bend, 1)
    $bend := $cb_v
  end if
end on

on listener
  if ($NI_SIGNAL_TYPE = $NI_SIGNAL_TIMER_BEAT)
    inc($tick)
    if ($pq_n > 0)
      call process_pending
    end if
    if ($arp_mode > 0 and $arp_n > 0 and $tick >= $arp_next)
      call arp_fire
      $lt_len := %rate_ticks[$arp_rate]
      $lt_sw := ($lt_len * $arp_swing) / 6
      if (($arp_step mod 2) = 1)
        $arp_next := $tick + $lt_len + $lt_sw
      else
        $arp_next := $tick + $lt_len - $lt_sw
      end if
    end if
  end if
end on

