on ui_control ($arp_mode)
  call upd_arp_mode
end on

on ui_control ($arp_rate)
  call upd_arp_rate
end on

on ui_control ($arp_oct)
  call upd_arp_oct
end on

on ui_control ($arp_gate)
  call upd_arp_gate
end on

on ui_control ($arp_swing)
  call upd_arp_swing
end on

on ui_control ($arp_latch)
  call upd_arp_latch
end on

on ui_control ($arp_accent)
  call upd_arp_accent
end on

on ui_control ($attack)
  call upd_attack
end on

on ui_control ($release)
  call upd_release
end on

on ui_control ($vrange)
  call upd_vrange
end on

on ui_control ($vcurve)
  call upd_vcurve
end on

on ui_control ($repeat_damp)
  call upd_repeat_damp
end on

on ui_control ($preset)
  call upd_preset
  call apply_preset
end on
]==]

-- remove the empty default group(s) the reset left behind
for i = initialGroups - 1, 0, -1 do
  local g = instrument.groups[i]
  if g and #g.zones == 0 then instrument.groups:remove(i) end
end

pcall(function() instrument.name = INSTRUMENT_NAME end)

-- attach the performance script (slot 1)
local scriptOk = pcall(function()
  local s = instrument.scripts[0]
  s.name = SCRIPT_NAME
  s.sourceCode = KSP_SOURCE
  s.bypass = false
end)
if not scriptOk then
  scriptOk = pcall(function()
    instrument.script.name = SCRIPT_NAME
    instrument.script.sourceCode = KSP_SOURCE
    instrument.script.bypass = false
  end)
end

print("------------------------------------------------------------")
print(INSTRUMENT_NAME .. ": " .. zoneCount .. " zones in " .. #instrument.groups .. " groups.")
if missing > 0 then
  print("WARNING: " .. missing .. " samples were not found. Is this script still inside")
  print("'" .. LIB_NAME .. "/Creator Tools'?")
end
if scriptOk then
  print("Performance script attached. If Kontakt shows it un-applied, open the")
  print("Script Editor and press Apply.")
else
  print("Could not attach the script automatically: open the Script Editor in Kontakt,")
  print("paste Resources/scripts/" .. SCRIPT_FILE .. " into slot 1 and press Apply.")
end
print("Now press PUSH, then save the instrument in Kontakt.")
